#[cfg(test)]
lazy_static::lazy_static! {
  // simulate the global C variables that point to the microkit shared memory regions.  In a full
  // microkit system we would be able to mutate the shared memory for out ports since they're r/w,
  // but we couldn't do that for in ports since they are read-only
  pub static ref IN_level: Mutex<Option<i32>> = Mutex::new(None);
  pub static ref IN_boolean_value: Mutex<Option<bool>> = Mutex::new(None);
  pub static ref IN_character_value: Mutex<Option<u8>> = Mutex::new(None);
  pub static ref IN_signed_8_value: Mutex<Option<i8>> = Mutex::new(None);
  pub static ref IN_signed_16_value: Mutex<Option<i16>> = Mutex::new(None);
  pub static ref IN_unsigned_8_value: Mutex<Option<u8>> = Mutex::new(None);
  pub static ref IN_unsigned_16_value: Mutex<Option<u16>> = Mutex::new(None);
  pub static ref IN_sample: Mutex<Option<i32>> = Mutex::new(None);
  pub static ref IN_flag: Mutex<Option<bool>> = Mutex::new(None);
  pub static ref IN_operating_state: Mutex<Option<Exhaustive_Monitor::OperatingState>> = Mutex::new(None);
  pub static ref IN_samples: Mutex<Option<Exhaustive_Monitor::Samples>> = Mutex::new(None);
  pub static ref IN_telemetry: Mutex<Option<Exhaustive_Monitor::Telemetry_i>> = Mutex::new(None);
  pub static ref IN_pulse: Mutex<Option<u8>> = Mutex::new(None);
  pub static ref OUT_healthy: Mutex<Option<bool>> = Mutex::new(None);
  pub static ref OUT_echo: Mutex<Option<i32>> = Mutex::new(None);
  pub static ref OUT_alert_result: Mutex<Option<bool>> = Mutex::new(None);
  pub static ref OUT_ack: Mutex<Option<u8>> = Mutex::new(None);
}

#[cfg(test)]
pub fn initialize_test_globals() {
  unsafe {
    *IN_level.lock().unwrap_or_else(|e| e.into_inner()) = None;
    *IN_boolean_value.lock().unwrap_or_else(|e| e.into_inner()) = None;
    *IN_character_value.lock().unwrap_or_else(|e| e.into_inner()) = None;
    *IN_signed_8_value.lock().unwrap_or_else(|e| e.into_inner()) = None;
    *IN_signed_16_value.lock().unwrap_or_else(|e| e.into_inner()) = None;
    *IN_unsigned_8_value.lock().unwrap_or_else(|e| e.into_inner()) = None;
    *IN_unsigned_16_value.lock().unwrap_or_else(|e| e.into_inner()) = None;
    *IN_sample.lock().unwrap_or_else(|e| e.into_inner()) = None;
    *IN_flag.lock().unwrap_or_else(|e| e.into_inner()) = None;
    *IN_operating_state.lock().unwrap_or_else(|e| e.into_inner()) = None;
    *IN_samples.lock().unwrap_or_else(|e| e.into_inner()) = None;
    *IN_telemetry.lock().unwrap_or_else(|e| e.into_inner()) = None;
    *IN_pulse.lock().unwrap_or_else(|e| e.into_inner()) = None;
    *OUT_healthy.lock().unwrap_or_else(|e| e.into_inner()) = None;
    *OUT_echo.lock().unwrap_or_else(|e| e.into_inner()) = None;
    *OUT_alert_result.lock().unwrap_or_else(|e| e.into_inner()) = None;
    *OUT_ack.lock().unwrap_or_else(|e| e.into_inner()) = None;
  }
}

#[cfg(test)]
pub fn get_level(value: *mut i32) -> bool
{
  unsafe {
    let guard = IN_level.lock().unwrap_or_else(|e| e.into_inner());
    *value = guard.expect("Not expecting None");
    true
  }
}

